const fs = require('fs');

function main() {
  let buf;
  try {
    buf = fs.readFileSync(0);
  } catch (e) {
    buf = fs.readFileSync('/dev/stdin');
  }
  const len = buf.length;
  let pos = 0;

  function nextInt() {
    while (pos < len && (buf[pos] < 48 || buf[pos] > 57)) pos++;
    let n = 0;
    while (pos < len && buf[pos] >= 48 && buf[pos] <= 57) {
      n = n * 10 + (buf[pos] - 48);
      pos++;
    }
    return n;
  }

  const E = nextInt();
  const M = nextInt();
  const D = nextInt();

  // Total de inteiros na entrada: 3 (E, M, D) + 2*M + 2*D + E (grupos: 3 * E/3)
  const total = 3 + 2 * (M + D) + E;
  const nums = new Int32Array(total);
  nums[0] = E; nums[1] = M; nums[2] = D;
  for (let i = 3; i < total; i++) {
    while (pos < len && (buf[pos] < 48 || buf[pos] > 57)) pos++;
    let n = 0;
    while (pos < len && buf[pos] >= 48 && buf[pos] <= 57) {
      n = n * 10 + (buf[pos] - 48);
      pos++;
    }
    nums[i] = n;
  }

  const sameBase = 3;              // pares "devem estar juntos": 2*M inteiros
  const diffBase = 3 + 2 * M;      // pares "não devem estar juntos": 2*D inteiros
  const groupBase = 3 + 2 * (M + D); // grupos: E inteiros

  // Mapeia cada estudante para o índice do seu grupo
  const group = new Int32Array(E + 1);
  const G = E / 3;
  for (let g = 0, o = groupBase; g < G; g++, o += 3) {
    group[nums[o]] = g;
    group[nums[o + 1]] = g;
    group[nums[o + 2]] = g;
  }

  let ans = 0;
  // Restrição "juntos" violada se estiverem em grupos diferentes
  for (let i = 0, o = sameBase; i < M; i++, o += 2) {
    if (group[nums[o]] !== group[nums[o + 1]]) ans++;
  }
  // Restrição "separados" violada se estiverem no mesmo grupo
  for (let i = 0, o = diffBase; i < D; i++, o += 2) {
    if (group[nums[o]] === group[nums[o + 1]]) ans++;
  }

  process.stdout.write(ans + '\n');
}

main();
